def _get_attr_and_option(self, names):
    """Get the attribute or plugin option for a config option name.

    `names` is a "section:option" name.  Returns a 2-tuple:
    (attr-name, None) for a regular option, or (None, (plugin, option))
    for a plugin option.  Raises CoverageException if the option is
    unknown.

    """
    for option_spec in self.CONFIG_FILE_OPTIONS:
        attr, where = option_spec[:2]
        if where == names:
            return attr, None

    # A section that isn't one of ours could be a plugin's section.
    plugin, _, option = names.partition(":")
    if plugin in self.plugins:
        return None, (plugin, option)

    raise CoverageException("Unknown configuration option: %r" % names)

# TODO: docs for this.
def __setitem__(self, names, value):
    attr, plugin_option = self._get_attr_and_option(names)
    if attr is not None:
        setattr(self, attr, value)
    else:
        plugin, option = plugin_option
        self.plugin_options.setdefault(plugin, {})[option] = value

# TODO: docs for this.
def __getitem__(self, names):
    attr, plugin_option = self._get_attr_and_option(names)
    if attr is not None:
        return getattr(self, attr)
    else:
        plugin, option = plugin_option
        return self.plugin_options.get(plugin, {}).get(option)
